//! Per-instance key/value storage (data/storage/<instance>.json).

use serde_json::{Map, Value};
use std::path::{Path, PathBuf};

use crate::error::{Error, Result};
use crate::store;

pub const MAX_BYTES: usize = 1024 * 1024;
const MAX_KEY: usize = 128;

pub struct Storage {
    dir: PathBuf,
}

impl Storage {
    pub fn new(dir: &Path) -> Storage {
        Storage { dir: dir.to_path_buf() }
    }

    fn file(&self, instance: &str) -> PathBuf {
        // Instance ids are generated by us (uuid), but never trust a path segment.
        let safe: String = instance.chars().filter(|c| c.is_ascii_alphanumeric() || *c == '-').collect();
        self.dir.join(format!("{safe}.json"))
    }

    pub fn all(&self, instance: &str) -> Map<String, Value> {
        store::load_json(&self.file(instance))
    }

    pub fn get(&self, instance: &str, key: &str) -> Value {
        self.all(instance).remove(key).unwrap_or(Value::Null)
    }

    /// Sets a key. `Value::Null` deletes it.
    pub fn set(&self, instance: &str, key: &str, value: Value) -> Result<()> {
        if key.is_empty() || key.len() > MAX_KEY {
            return Err(Error::msg("storage key must be 1–128 characters"));
        }
        let mut all = self.all(instance);
        if value.is_null() {
            all.remove(key);
        } else {
            all.insert(key.to_string(), value);
        }
        if serde_json::to_vec(&all)?.len() > MAX_BYTES {
            return Err(Error::msg("widget storage is full (1 MB limit)"));
        }
        store::save_json(&self.file(instance), &all)
    }

    pub fn delete_instance(&self, instance: &str) {
        let _ = std::fs::remove_file(self.file(instance));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn set_get_delete_and_limits() {
        let tmp = tempfile::tempdir().unwrap();
        let s = Storage::new(tmp.path());
        s.set("abc", "note", json!("hello")).unwrap();
        assert_eq!(s.get("abc", "note"), json!("hello"));
        assert_eq!(s.get("other", "note"), Value::Null);
        s.set("abc", "note", Value::Null).unwrap();
        assert_eq!(s.get("abc", "note"), Value::Null);
        assert!(s.set("abc", "", json!(1)).is_err());
        assert!(s.set("abc", "big", json!("x".repeat(MAX_BYTES))).is_err());
        // path traversal in the instance id is neutralised
        s.set("../../evil", "k", json!(1)).unwrap();
        assert!(tmp.path().join("evil.json").exists());
    }
}
